  var body = parts.join(joiner) + (n > shown ? ' + … (' + n + ' terms)' : '');
  var lead = wave === 'square' ? '(4/π)' : wave === 'sawtooth' ? '(2/π)' : '(8/π²)';
  return 'f(x) ≈ ' + lead + '·[ ' + body + ' ]';
