    pdf: function (x) { return 0.5 * cltNormal(x, 0.25, 0.08) + 0.5 * cltNormal(x, 0.75, 0.08); },
    draw: function () { return (Math.random() < 0.5 ? 0.25 : 0.75) + 0.08 * cltGauss(); } }
};

